#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 15b2: the video workspace in five languages
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part (plan: claude/language-plan.md):
#   * the video page is translated in Spanish, French, Arabic and
#     Portuguese: player, timeline, Summary, Chapters, Key moments and the
#     other tabs, the chapter editor, transcript, notes, Ask (suggested
#     questions are asked in the reader's language), clips, Publish to
#     YouTube, Share, Export, details, course strip, processing status, the
#     Ownership panel, and the notes about file formats
#   * known processing steps are named in the reader's language
#   * sizes and dates in the Ownership panel follow the reader's language
#   * in Arabic: lists, borders and the Ask button sit on the right side;
#     the player and the timeline stay left to right; titles, transcript
#     lines, chapters and answers keep their own direction
#   * progress bars follow the page direction, as the library cards do
#   * still off by default: production is unchanged while
#     NEXT_PUBLIC_LANGUAGES is not on
#
#   FRONTEND   23 changed. No migration, no new package
#
#   ./vm_lang_b2.sh            apply (needs Part 14f on the branch)
#   ./vm_lang_b2.sh --force    apply even if local files differ from GitHub
#   ./vm_lang_b2.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="useMediaText"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_lang_b2_backups"

