  "frontend/src/components/video/IntelligenceStrip.tsx"
  "frontend/src/components/video/ChapterEditor.tsx"
  "frontend/src/components/video/NotesPanel.tsx"
  "frontend/src/components/chat/ChatPanel.tsx"
  "frontend/src/components/video/ClipsPanel.tsx"
  "frontend/src/components/video/PublishPanel.tsx"
  "frontend/src/components/video/ShareButton.tsx"
  "frontend/src/components/video/VideoDetails.tsx"
  "frontend/src/components/video/ExportMenu.tsx"
  "frontend/src/components/video/CourseStrip.tsx"
  "frontend/src/components/video/ProcessingStatus.tsx"
  "frontend/src/components/video/OnChainProof.tsx"
  "frontend/src/components/upload/UploadZone.tsx"
