B64_M22
verify "$TMPD/m22" "${NEW_MOD[22]}" "frontend/src/components/upload/UploadZone.tsx"

grep -q -- '"videoPage"' "$TMPD/m0" || die "en.json payload is wrong. Aborting."
grep -q -- '"uploadPage"' "$TMPD/m0" || die "en.json payload lost 15b1. Aborting."
grep -q -- 'اسأل عن هذا الفيديو' "$TMPD/m3" || die "frontend/src/messages/ar.json payload is wrong. Aborting."
grep -q -- 'export function useMediaText' "$TMPD/m5" || die "media.ts payload is wrong. Aborting."
grep -q -- 'useTranslations("videoPage")' "$TMPD/m6" || die "video page payload is wrong. Aborting."
grep -q -- 'useTranslations("player")' "$TMPD/m7" || die "VideoPlayer.tsx payload is wrong. Aborting."
grep -q -- 'useTranslations("ask")' "$TMPD/m13" || die "ChatPanel.tsx payload is wrong. Aborting."
grep -q -- 'useTranslations("proof")' "$TMPD/m21" || die "OnChainProof.tsx payload is wrong. Aborting."
grep -q -- 'useTranslations("upload")' "$TMPD/m22" || die "UploadZone.tsx payload lost 15b1. Aborting."
say "23 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in ${ADD[@]+"${ADD[@]}"}; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in ${ADD[@]+"${ADD[@]}"}; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in ${ADD[@]+"${ADD[@]}"}; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Part 15b2 (the video workspace)."
say "No migration and no new package."
say "Install the new package and verify before pushing:"
say "  (cd frontend && npx tsc --noEmit && npm run build)"
say "To see the languages on the preview only: Vercel, the project, Settings,"
say "Environment Variables, NEXT_PUBLIC_LANGUAGES = on, environment Preview only."
say "Leave it unset for Production until Part 15c."
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_lang_b2.sh --revert"
